def histogram(test):
    if not test:
        return {}

    counts = {}
    letters = test.split(' ')

    max_count = 0
    max_letters = set()

    for letter in letters:
        counts[letter] = counts.get(letter, 0) + 1
        if counts[letter] > max_count:
            max_count = counts[letter]
            max_letters = {letter}
        elif counts[letter] == max_count:
            max_letters.add(letter)

    result = {letter: max_count for letter in max_letters}
    return result

